--!strict
--!optimize 2

local gifWidth = 24
local gifHeight = 22
local frameDelay = 0.134
local palette = {
    Color3.fromRGB(171, 87, 68),
    Color3.fromRGB(148, 106, 113),
    Color3.fromRGB(90, 46, 43),
    Color3.fromRGB(130, 82, 83),
    Color3.fromRGB(66, 29, 28),
    Color3.fromRGB(181, 69, 28),
    Color3.fromRGB(183, 71, 31),
    Color3.fromRGB(106, 46, 34),
    Color3.fromRGB(177, 71, 37),
    Color3.fromRGB(148, 131, 157),
    Color3.fromRGB(141, 58, 34),
    Color3.fromRGB(188, 73, 32),
    Color3.fromRGB(23, 9, 14),
    Color3.fromRGB(166, 149, 177),
    Color3.fromRGB(110, 63, 62),
    Color3.fromRGB(178, 67, 26),
}
local frames = {
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
}

local cellSize = 12
local speed = 200
local imageWidth = gifWidth * cellSize
local imageHeight = gifHeight * cellSize

local runId = os.clock()
_G.GifDrawingRunId = runId

local pool = {}
local offsets = {}
local used = 0
local x, y = 100, 100
local velocityX, velocityY = speed, speed

local function ScreenSize()
    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize
    if viewport then return viewport.X, viewport.Y end
    return 1920, 1080
end

local function GetSquare(index)
    local square = pool[index]
    if not square then
        square = Drawing.new("Square")
        square.Filled = true
        square.Thickness = 0
        pool[index] = square
    end
    return square
end

local function DrawFrame(frame)
    used = 0
    for row = 0, gifHeight - 1 do
        local rowStart = row * gifWidth
        local column = 0
        while column < gifWidth do
            local colour = string.byte(frame, rowStart + column + 1)
            local runEnd = column + 1
            while runEnd < gifWidth and string.byte(frame, rowStart + runEnd + 1) == colour do
                runEnd += 1
            end

            used += 1
            local square = GetSquare(used)
            offsets[used] = vector.create(column * cellSize, row * cellSize, 0)
            square.Size = vector.create((runEnd - column) * cellSize, cellSize, 0)
            square.Color = palette[tonumber(string.char(colour), 16) + 1]
            square.Visible = true

            column = runEnd
        end
    end

    for index = used + 1, #pool do
        pool[index].Visible = false
    end
end

local function Move(dt)
    local width, height = ScreenSize()
    local maxX, maxY = width - imageWidth, height - imageHeight
    x += velocityX * dt
    y += velocityY * dt
    if x < 0 then
        x, velocityX = 0, speed
    elseif x > maxX then
        x, velocityX = maxX, -speed
    end
    if y < 0 then
        y, velocityY = 0, speed
    elseif y > maxY then
        y, velocityY = maxY, -speed
    end

    local origin = vector.create(x, y, 0)
    for index = 1, used do
        pool[index].Position = origin + offsets[index]
    end
end

task.spawn(function()
    local index = 1
    local last = os.clock()
    local nextFrame = last
    while _G.GifDrawingRunId == runId do
        local now = os.clock()
        if now >= nextFrame then
            nextFrame = math.max(nextFrame + frameDelay, now)
            DrawFrame(frames[index])
            index = index % #frames + 1
        end
        Move(math.min(now - last, .1))
        last = now
        task.wait()
    end

    for _, square in pool do
        square:Remove()
    end
end)
